}

# ANSI color names
ANSI_COLOR_NAMES = {
    'black': 0, 'red': 1, 'green': 2, 'yellow': 3, 'blue': 4,
    'magenta': 5, 'cyan': 6, 'white': 7,
    'brightblack': 8, 'brightred': 9, 'brightgreen': 10, 'brightyellow': 11,
    'brightblue': 12, 'brightmagenta': 13, 'brightcyan': 14, 'brightwhite': 15,
    'purple': 5,  # synonym for magenta
}

def rgb_to_256(r, g, b):
    """Convert RGB to nearest 256-color index."""
    # Check if it's a grayscale color
    if r == g == b:
        if r < 8:
            return 16
        if r > 248:
            return 231
        return round((r - 8) / 247 * 24) + 232

    # Cube colors
    ri = round(r / 255 * 5)
    gi = round(g / 255 * 5)
    bi = round(b / 255 * 5)
    return 16 + 36 * ri + 6 * gi + bi

def parse_color(color_str, true_color=False):
    """Parse a color specification.
    Returns (type, value) where:
    - type='ansi256', value=int (0-255)
    - type='rgb', value=(r,g,b)
    - type='none' (no color)
    - type='normal' (terminal default)
    - type='syntax' (use syntax highlighting)
    - type='auto' (automatic)
    """
    if not color_str:
        return ('none', None)

    s = color_str.strip().lower()

    if s == 'normal':
        return ('normal', None)
    if s == 'syntax':
        return ('syntax', None)
    if s == 'auto':
        return ('auto', None)
    if s == 'raw':
        return ('raw', None)

    # ANSI color name
    if s in ANSI_COLOR_NAMES:
        n = ANSI_COLOR_NAMES[s]
        return ('ansi256', n)

    # CSS color name
    if s in CSS_COLORS:
        r, g, b = CSS_COLORS[s]
        if true_color:
            return ('rgb', (r, g, b))
        else:
            return ('ansi256', rgb_to_256(r, g, b))

    # Hex color
    hex_match = re.match(r'^#?([0-9a-f]{6})$', s)
    if hex_match:
        hex_str = hex_match.group(1)
        r = int(hex_str[0:2], 16)
        g = int(hex_str[2:4], 16)
        b = int(hex_str[4:6], 16)
        if true_color:
            return ('rgb', (r, g, b))
        else:
            return ('ansi256', rgb_to_256(r, g, b))

    # Number (0-255)
    try:
        n = int(s)
        if 0 <= n <= 255:
            return ('ansi256', n)
    except ValueError:
        pass

    return ('none', None)

class Style:
    """Represents a display style (fg color, bg color, attributes)."""

    def __init__(self):
        self.fg = None  # (type, value)
        self.bg = None  # (type, value)
        self.bold = False
        self.italic = False
        self.underline = False
        self.overline = False
        self.strike = False
        self.dim = False
        self.blink = False
        self.reverse = False
        self.hidden = False
        self.omit = False
        self.raw = False

    def copy(self):
        s = Style()
        s.fg = self.fg
        s.bg = self.bg
        s.bold = self.bold
        s.italic = self.italic
        s.underline = self.underline
        s.overline = self.overline
        s.strike = self.strike
        s.dim = self.dim
        s.blink = self.blink
        s.reverse = self.reverse
        s.hidden = self.hidden
        s.omit = self.omit
        s.raw = self.raw
        return s

    @classmethod
