        t, v = bg
        if t == 'ansi256':
            if v < 8:
                return ansi_standard_bg(v)
            elif v < 16:
                return ansi_standard_bg(v)
            else:
                return ansi_bg(v)
        elif t == 'rgb':
            return ansi_bg_rgb(*v)
        return ''

    def render_attrs(self):
