        r = ''
        if self.bold:
            r += ansi_bold()
        if self.italic:
            r += ansi_italic()
        if self.underline:
            r += ansi_ul()
        if self.overline:
            r += ansi_ol()
        if self.strike:
            r += ansi_strike()
        if self.dim:
            r += ansi_dim()
        if self.blink:
            r += ansi_blink()
        if self.reverse:
            r += ansi_reverse()
        if self.hidden:
            r += ansi_hidden()
        return r

    def apply(self, text, syntax_color=None):
        """Apply this style to text, returning styled string."""
        if self.omit:
            return ''
        if self.raw:
            return text

        fg_type = self.fg[0] if self.fg else None
        bg_type = self.bg[0] if self.bg else None

        result = ansi_reset()

        if fg_type == 'syntax' and syntax_color:
            result += syntax_color
        elif fg_type not in (None, 'syntax', 'auto', 'normal'):
            result += self.render_fg()

        if bg_type not in (None, 'syntax', 'auto', 'normal'):
            result += self.render_bg()

        result += self.render_attrs()
        result += text
        result += ansi_reset()

        return result

