def get_token_color(ttype, value, theme_colors):
    """Map a Pygments token type to a 256-color number."""
    if not PYGMENTS_AVAILABLE:
        return theme_colors['name']

    tc = theme_colors

    # Comments
    if ttype in Comment or ttype is Comment:
        return tc['comment']

    # Strings
    if ttype in String or ttype in Literal or ttype is String or ttype is Literal:
        return tc['string']

    # Numbers
    if ttype in Number or ttype is Number:
        return tc['number']

    # Keywords
    if ttype is Keyword.Declaration or ttype is Keyword.Type:
        # 'def', 'class' in Python are declaration keywords -> use keyword_declaration
        if value in ('def', 'class', 'fn', 'let', 'const', 'var', 'struct', 'enum',
                     'impl', 'trait', 'type', 'fun', 'func', 'function', 'sub',
                     'procedure', 'module', 'namespace'):
            return tc['keyword_declaration']
        return tc['keyword']

    if ttype is Keyword.Constant:
        # None, True, False -> treat as numbers/constants
        return tc['number']

    if ttype in Keyword or ttype is Keyword:
        return tc['keyword']

    # Names
    if ttype is Name.Function or ttype is Name.Function.Magic:
        return tc['name_function']

    if ttype is Name.Class:
        return tc['name_class']

    if ttype is Name.Builtin:
        # Check if it's a type or a function
        if value in PYTHON_BUILTIN_TYPES:
            return tc['name_builtin_type']
        return tc['name_builtin']

    if ttype is Name.Builtin.Pseudo:
        return tc['name_other']  # self, cls, etc.

    if ttype is Name.Decorator:
        return tc['name_other']

    if ttype is Name.Attribute:
        return tc['name_builtin']

    if ttype is Name.Tag:
        return tc['keyword']

    if ttype in Name or ttype is Name:
        return tc['name']

    # Operators
    if ttype in Operator or ttype is Operator:
        return tc['operator']

    # Punctuation
    if ttype in Punctuation or ttype is Punctuation:
        return tc['punctuation']

    # Generic/Text
    return tc['name']


def syntax_highlight_line(code, lexer, theme_colors):
    """Return list of (text, color_num) tuples for a line of code."""
    if not PYGMENTS_AVAILABLE or lexer is None:
        return [(code, theme_colors['name'])]

    try:
        tokens = list(lex(code, lexer))
    except Exception:
        return [(code, theme_colors['name'])]

    result = []
    for ttype, value in tokens:
        if value == '\n' or value == '':
            continue
        color = get_token_color(ttype, value, theme_colors)
        result.append((value, color))

    return result


def get_lexer_for_file(filename, default_lang='txt'):
    """Get Pygments lexer for a filename."""
    if not PYGMENTS_AVAILABLE:
        return None

    if not filename:
        filename = default_lang

    try:
        return get_lexer_for_filename(filename, stripnl=False, stripall=False)
    except Exception:
        pass

    try:
        return get_lexer_by_name(default_lang or 'text', stripnl=False, stripall=False)
    except Exception:
        pass

    return None


def strip_ansi(text):
    """Remove ANSI escape codes from text."""
    return re.sub(r'\x1b\[[0-9;]*m', '', text)


def visible_len(text):
    """Length of text without ANSI escape codes."""
    return len(strip_ansi(text))


def get_terminal_width():
    """Get terminal width."""
    try:
        return os.get_terminal_size().columns
    except Exception:
        return 80


