            m = re.match(r'^\[(\w+)(?:\s+"([^"]+)")?\s*\]', line_stripped)
            if m:
                section = m.group(1).lower()
                subsection = m.group(2)
                if section == 'delta':
                    in_delta_section = True
                    current_feature = subsection  # None means main delta section
                else:
                    in_delta_section = False
                    current_feature = None
        elif in_delta_section and '=' in line_stripped:
            key, _, val = line_stripped.partition('=')
            key = key.strip().replace('-', '_')
            val = val.strip()
            # Remove quotes
            if val.startswith('"') and val.endswith('"'):
                val = val[1:-1]
            elif val.startswith("'") and val.endswith("'"):
                val = val[1:-1]

            if current_feature is None:
                settings[key] = val
            else:
