def compute_word_diff(minus_line, plus_line, word_regex=r'\w+'):
    """Compute word-level diff between two lines.
    Returns (minus_regions, plus_regions) where each region is (start, end, is_changed)."""

    # Split into tokens preserving positions
    def tokenize(line):
        tokens = []
        pos = 0
        for m in re.finditer(word_regex, line):
            if m.start() > pos:
                tokens.append((pos, m.start(), line[pos:m.start()], False))  # non-word
            tokens.append((m.start(), m.end(), m.group(), True))  # word
            pos = m.end()
        if pos < len(line):
            tokens.append((pos, len(line), line[pos:], False))
        return tokens

    minus_tokens = tokenize(minus_line)
    plus_tokens = tokenize(plus_line)

    minus_words = [t[2] for t in minus_tokens]
    plus_words = [t[2] for t in plus_tokens]

    # Compute diff using SequenceMatcher
    sm = difflib.SequenceMatcher(None, minus_words, plus_words, autojunk=False)

    minus_changed = [True] * len(minus_tokens)
    plus_changed = [True] * len(plus_tokens)

    for op, i1, i2, j1, j2 in sm.get_opcodes():
        if op == 'equal':
            for i in range(i1, i2):
                minus_changed[i] = False
            for j in range(j1, j2):
                plus_changed[j] = False

    return minus_tokens, minus_changed, plus_tokens, plus_changed


