        n = s.fg[1]
        if n < 8:
            result += ansi_standard_fg(n)
        else:
            result += ansi_fg(n)
    elif s.fg and s.fg[0] == 'rgb':
        result += ansi_fg_rgb(*s.fg[1])

    if s.bg and s.bg[0] == 'ansi256':
        n = s.bg[1]
        if n < 8:
            result += ansi_standard_bg(n)
        else:
            result += ansi_bg(n)
    elif s.bg and s.bg[0] == 'rgb':
        result += ansi_bg_rgb(*s.bg[1])

    if s.bold:
        result += ansi_bold()
    if s.italic:
        result += ansi_italic()
    if s.underline:
        result += ansi_ul()
    if s.overline:
        result += ansi_ol()
    if s.strike:
        result += ansi_strike()
    if s.dim:
        result += ansi_dim()
    if s.blink:
