class DiffProcessor:
    """Process and format diff output."""

    def __init__(self, config):
        self.config = config
        self.output_lines = []
        self.current_file_old = None
        self.current_file_new = None
        self.current_lexer = None
        self.is_git_diff = False
        self.theme_colors = config.get_theme_colors()
        self.hunk_count = 0
        self.line_context = []  # Buffer for accumulating lines

    def get_lexer(self, filename):
        """Get Pygments lexer for a file."""
        if filename is None:
            return None
        # Remove a/ b/ prefix from git diff
        fn = filename
        if fn.startswith('a/') or fn.startswith('b/'):
            fn = fn[2:]
        return get_lexer_for_file(fn, self.config.default_language)

    def get_syntax_tokens(self, text):
        """Get syntax highlighting tokens for a line of text."""
        if not PYGMENTS_AVAILABLE or self.current_lexer is None:
            return [(text, self.theme_colors['name'])]

        # Get full token list for this line
        tokens = syntax_highlight_line(text, self.current_lexer, self.theme_colors)
        return tokens

    def format_line_number(self, fmt, nm, np):
        """Format a line number string."""
        # Simple format substitution for {nm:...} and {np:...}
        result = fmt

        def replace_placeholder(m):
            name = m.group(1)
            spec = m.group(2)
            if name == 'nm':
                val = str(nm) if nm is not None else ''
            elif name == 'np':
                val = str(np) if np is not None else ''
            else:
                return m.group(0)

            if spec:
                # Apply format spec
                try:
                    val = format(val, spec)
                except Exception:
                    pass
            return val

        result = re.sub(r'\{(nm|np):([^}]*)\}', replace_placeholder, result)
        result = re.sub(r'\{(nm|np)\}', lambda m: str(nm if m.group(1)=='nm' else np) if (nm if m.group(1)=='nm' else np) is not None else '', result)

        return result

    def render_line_numbers(self, nm, np, line_type):
        """Render line number columns."""
        if not self.config.line_numbers:
            return ''

        left_fmt = self.config.line_numbers_left_format
        right_fmt = self.config.line_numbers_right_format

        left_text = self.format_line_number(left_fmt, nm, np)
        right_text = self.format_line_number(right_fmt, nm, np)

        # Determine colors based on line type
        if line_type == 'minus':
            left_style = self.config.line_numbers_minus_style
            right_style = self.config.line_numbers_minus_style
        elif line_type == 'plus':
            left_style = self.config.line_numbers_plus_style
            right_style = self.config.line_numbers_plus_style
        else:
            left_style = self.config.line_numbers_zero_style
            right_style = self.config.line_numbers_zero_style

        # 'auto' means use file header color (blue)
        def resolve_style(s):
            if s == 'auto':
                return self.config.file_style
            return s

        left_style = resolve_style(left_style)
        right_style = resolve_style(right_style)

        left_fg = get_style_fg_esc(self.config.line_numbers_left_style 
                                   if self.config.line_numbers_left_style != 'auto' 
                                   else self.config.file_style, 
                                   self.config.true_color)
        right_fg = get_style_fg_esc(self.config.line_numbers_right_style
                                    if self.config.line_numbers_right_style != 'auto'
                                    else self.config.file_style,
                                    self.config.true_color)

        if line_type == 'minus':
            num_color = get_style_fg_esc(
                self.config.line_numbers_minus_style if self.config.line_numbers_minus_style != 'auto' 
                else '88', self.config.true_color)
            if not num_color:
                num_color = ansi_fg(88) if self.config.is_dark() else ansi_fg(196)
        elif line_type == 'plus':
            num_color = get_style_fg_esc(
                self.config.line_numbers_plus_style if self.config.line_numbers_plus_style != 'auto'
                else '28', self.config.true_color)
            if not num_color:
                num_color = ansi_fg(28) if self.config.is_dark() else ansi_fg(22)
        else:
            num_color = get_style_fg_esc(
                self.config.line_numbers_zero_style if self.config.line_numbers_zero_style != 'auto'
                else '238', self.config.true_color)
            if not num_color:
                num_color = ansi_fg(238)

        reset = ansi_reset()
        file_color = get_style_fg_esc(self.config.file_style, self.config.true_color)
        if not file_color:
            file_color = ansi_standard_fg(4)  # blue

        # Replace separators in format with colored versions
        def colorize_format(fmt_text, nm_val, np_val, num_col, sep_col):
            result = ''
            i = 0
            in_placeholder = False
            while i < len(fmt_text):
                if fmt_text[i] == '{':
                    in_placeholder = True
                    result += sep_col  # reset color before placeholder content
                    j = fmt_text.find('}', i)
                    if j == -1:
                        result += fmt_text[i:]
                        break
                    placeholder = fmt_text[i:j+1]
                    inner = fmt_text[i+1:j]
                    colon = inner.find(':')
                    name = inner[:colon] if colon >= 0 else inner
                    spec = inner[colon+1:] if colon >= 0 else ''
                    if name == 'nm':
                        val = str(nm_val) if nm_val is not None else ''
                    elif name == 'np':
                        val = str(np_val) if np_val is not None else ''
                    else:
                        val = ''
                    if spec:
                        try:
                            val = format(val, spec)
                        except Exception:
                            pass
                    result += num_col + val + reset
                    i = j + 1
                    in_placeholder = False
                else:
                    result += sep_col + fmt_text[i]
                    i += 1
            return result

        left_rendered = colorize_format(left_fmt, nm, np, num_color, file_color)
        right_rendered = colorize_format(right_fmt, nm, np, num_color, file_color)

        return reset + left_rendered + reset + right_rendered + reset

