def process_input(input_lines, config):
    """Process input lines and return formatted output lines."""

    if config.raw:
        return [l.rstrip('\n') for l in input_lines]

    if config.parse_ansi:
        return parse_ansi_mode(input_lines)

    if config.diff_highlight:
        return diff_highlight_mode(input_lines, config)

    if config.diff_so_fancy:
        return diff_so_fancy_mode(input_lines, config)

    if config.color_only:
        return process_color_only(input_lines, config)

    # Normal diff processing
    lines = [l.rstrip('\n') for l in input_lines]
    return process_diff_output(lines, config)


def output_lines(lines, config, is_tty):
    """Output lines, using pager if needed."""
    output = '\n'.join(lines)
    if output and not output.endswith('\n'):
        output += '\n'

    use_pager = False
    if config.paging == 'always':
        use_pager = True
    elif config.paging == 'auto' and is_tty:
        use_pager = True

    if use_pager and config.pager != 'none':
        pager = config.pager
        if not pager:
            pager = os.environ.get('PAGER', 'less')

        if pager and pager != 'none':
            try:
                env = os.environ.copy()
                env.setdefault('LESS', 'FRX')
                env.setdefault('LV', '-c')
                proc = subprocess.Popen(
                    pager,
                    shell=True,
                    stdin=subprocess.PIPE,
                    env=env,
                )
                proc.stdin.write(output.encode('utf-8', errors='replace'))
                proc.stdin.close()
                proc.wait()
                return
            except Exception:
                pass

    sys.stdout.write(output)
    sys.stdout.flush()


def main():
    import sys

    # Check for version/help first
    argv = sys.argv[1:]

    if '--version' in argv or '-V' in argv:
        print('delta 0.18.2')
        sys.exit(0)

    if '--help' in argv:
        # Output full help
        sys.stdout.write(LONG_HELP)
        sys.exit(0)

    if '-h' in argv:
        sys.stdout.write(SHORT_HELP)
        sys.exit(0)

    # Parse args
    try:
        args = parse_args(argv)
    except SystemExit as e:
        sys.exit(e.code)

    config = args_to_config(args)
    config.resolve_auto_colors()

    # Handle special output modes
    if config.list_syntax_themes:
        for dark_light, name in list_syntax_themes():
            print(f'{dark_light}\t{name}')
        sys.exit(0)

    if config.list_languages:
        for line in list_languages_output():
            print(line)
        sys.exit(0)

    if config.show_colors:
        for line in show_colors_output():
            print(line)
        sys.exit(0)

    if config.show_config:
        for line in show_config_output(config):
            print(line)
        sys.exit(0)

    if config.show_syntax_themes or config.show_themes:
        for line in show_syntax_themes_output(config):
            print(line)
        sys.exit(0)

    if config.generate_completion:
        # Generate shell completion (simplified)
        print(f'# Shell completion for {config.generate_completion} not implemented')
        sys.exit(0)

