            input_lines = input_data.decode('utf-8', errors='replace').splitlines(keepends=True)
        except Exception as e:
            print(f'delta: error: {e}', file=sys.stderr)
            sys.exit(1)
    else:
        # Read from stdin
        if sys.stdin.isatty() and not config.minus_file:
