        except Exception as e:
            print(f'delta: error reading stdin: {e}', file=sys.stderr)
            sys.exit(1)

    if not input_lines:
        sys.exit(0)

    # Process input
    output = process_input(input_lines, config)

    is_tty = sys.stdout.isatty()
    output_lines(output, config, is_tty)


