        if os.path.exists(help_file):
            with open(help_file) as f:
                content = f.read()
            # Extract the help text between the code fences
            m = re.search(r'```txt\n(.*?)```', content, re.DOTALL)
            if m:
                sys.stdout.write(m.group(1))
                return 0
        # Fallback to stored help
        sys.stdout.write(SHORT_HELP)
        return 0

    if '-h' in argv:
        sys.stdout.write(SHORT_HELP)
        return 0

    # Parse args
    parser = make_argparser()
    try:
        args, unknown = parser.parse_known_args(argv)
    except SystemExit as e:
        # Produce delta-style error for unknown args
        if unknown:
            print(f'\x1b[1m\x1b[31merror:\x1b[0m unexpected argument \'\x1b[33m{unknown[0]}\x1b[0m\' found')
        return 1

