        return 0

    if args.show_syntax_themes or args.show_themes:
        for line in show_syntax_themes(cfg):
            print(line)
        return 0

    if args.show_colors:
        # Show 256 colors
        for i in range(256):
            print(f'{bg256(i)}  {RESET} {i}')
        return 0

    if getattr(args, 'generate_completion', None):
        print(f'# Shell completion not implemented')
        return 0

    # Two-file diff mode
    if cfg.minus_file and cfg.plus_file:
        try:
            diff_args = ['-u']
            if cfg.diff_args:
                diff_args.extend(cfg.diff_args.split())
            result = subprocess.run(
                ['diff'] + diff_args + [cfg.minus_file, cfg.plus_file],
                stdout=subprocess.PIPE, stderr=subprocess.PIPE
            )
            input_bytes = result.stdout
            if not input_bytes and result.returncode == 0:
                return 0
            input_lines = input_bytes.decode('utf-8', errors='replace').splitlines(keepends=True)
        except Exception as e:
            print(f'delta: {e}', file=sys.stderr)
            return 1
    elif not sys.stdin.isatty():
        try:
            input_bytes = sys.stdin.buffer.read()
            input_lines = input_bytes.decode('utf-8', errors='replace').splitlines(keepends=True)
        except Exception as e:
            print(f'delta: {e}', file=sys.stderr)
            return 1
    else:
        return 0

    if not input_lines:
        return 0

    # Process input
    if cfg.raw_mode:
        output = process_raw(input_lines, cfg)
    elif cfg.parse_ansi:
        output = process_parse_ansi(input_lines, cfg)
    elif cfg.diff_highlight:
        output = process_diff_highlight(input_lines, cfg)
    elif cfg.diff_so_fancy:
        output = process_diff_so_fancy(input_lines, cfg)
    elif cfg.color_only:
        output = process_color_only(input_lines, cfg)
    else:
        output = process_diff(input_lines, cfg)

    # Output
    text = '\n'.join(output)
    if output and not text.endswith('\n'):
        text += '\n'

    is_tty = sys.stdout.isatty()
    use_pager = (cfg.paging == 'always') or (cfg.paging == 'auto' and is_tty)

    if use_pager and cfg.pager != 'none':
        pager = cfg.pager or os.environ.get('PAGER', 'less')
        if pager and pager != 'none':
            try:
                env = os.environ.copy()
                env.setdefault('LESS', 'FRX')
                proc = subprocess.Popen(pager, shell=True, stdin=subprocess.PIPE, env=env)
                proc.stdin.write(text.encode('utf-8', errors='replace'))
                proc.stdin.close()
                proc.wait()
                return 0
            except Exception:
                pass

